final class HtmlView extends BaseHtmlView{public array $items=[],$packages=[],$types=[],$stats=[],$filters=[];public function display($tpl=null):void{if(!Factory::getApplication()->getIdentity()->authorise('core.manage','com_kaarbooking'))throw new \RuntimeException('Not authorised',403);$app=Factory::getApplication();$db=Factory::getContainer()->get(\Joomla\Database\DatabaseInterface::class);$this->filters=['search'=>trim((string)$app->input->getString('filter_search','')),'status'=>$app->input->getCmd('filter_status'),'source'=>$app->input->getCmd('filter_source'),'from'=>(string)$app->input->getString('filter_from',''),'to'=>(string)$app->input->getString('filter_to','')];$q=$db->getQuery(true)->select('*')->from('#__kaar_bookings');if($this->filters['search']!=='')$q->where('(reference LIKE '.$db->quote('%'.$this->filters['search'].'%').' OR customer_name LIKE '.$db->quote('%'.$this->filters['search'].'%').' OR customer_phone LIKE '.$db->quote('%'.$this->filters['search'].'%').')');if($this->filters['status']!=='')$q->where('status='.$db->quote($this->filters['status']));if($this->filters['source']!=='')$q->where('source='.$db->quote($this->filters['source']));if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$this->filters['from']))$q->where('departure_at >= '.$db->quote($this->filters['from'].' 00:00:00'));if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$this->filters['to']))$q->where('departure_at <= '.$db->quote($this->filters['to'].' 23:59:59'));$q->order('created DESC');$this->items=$db->setQuery($q,0,500)->loadAssocList()?:[];$this->packages=$db->setQuery('SELECT id,title FROM #__kaar_packages WHERE state=1 ORDER BY title')->loadAssocList()?:[];$this->types=$db->setQuery('SELECT id,title FROM #__kaar_vehicle_types WHERE state=1 ORDER BY ordering,title')->loadAssocList()?:[];$this->stats=['total'=>(int)$db->setQuery('SELECT COUNT(*) FROM #__kaar_bookings')->loadResult(),'pending'=>(int)$db->setQuery("SELECT COUNT(*) FROM #__kaar_bookings WHERE status IN ('pending_admin_review',